-- 003_seed_all_dota_heroes_and_items.sql
-- Все 127 героев Dota 2, все предметы лавки/Рошана/нейтралки и 20 локаций карты

-- Обновляем внешний ключ в game_rounds на ON UPDATE CASCADE ON DELETE SET NULL, чтобы не затрагивать активные игры
ALTER TABLE public.game_rounds
  DROP CONSTRAINT IF EXISTS game_rounds_secret_word_id_fkey;

ALTER TABLE public.game_rounds
  ADD CONSTRAINT game_rounds_secret_word_id_fkey
  FOREIGN KEY (secret_word_id)
  REFERENCES public.dota_words(id)
  ON UPDATE CASCADE
  ON DELETE SET NULL;

-- Переводим старые короткие ID из первого сида на канонические ID Valve
UPDATE public.dota_words SET id = 'hero_nevermore' WHERE id = 'hero_sf' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'hero_nevermore');
UPDATE public.dota_words SET id = 'hero_phantom_assassin' WHERE id = 'hero_pa' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'hero_phantom_assassin');
