UPDATE public.dota_words SET id = 'item_smoke_of_deceit' WHERE id = 'item_smoke' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'item_smoke_of_deceit');
UPDATE public.dota_words SET id = 'item_ultimate_scepter' WHERE id = 'item_aghanim' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'item_ultimate_scepter');
UPDATE public.dota_words SET id = 'item_invis_sword' WHERE id = 'item_shadow_blade' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'item_invis_sword');
UPDATE public.dota_words SET id = 'item_ward_observer' WHERE id = 'item_ward' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'item_ward_observer');
UPDATE public.dota_words SET id = 'item_hand_of_midas' WHERE id = 'item_midas' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'item_hand_of_midas');
UPDATE public.dota_words SET id = 'item_sheepstick' WHERE id = 'item_hex' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'item_sheepstick');
UPDATE public.dota_words SET id = 'item_tpscroll' WHERE id = 'item_tp' AND NOT EXISTS (SELECT 1 FROM public.dota_words WHERE id = 'item_tpscroll');

ON CONFLICT (id) DO UPDATE SET
  category = EXCLUDED.category,
  name_ru = EXCLUDED.name_ru,
  name_en = EXCLUDED.name_en,
  hint = EXCLUDED.hint,
  image_url = EXCLUDED.image_url;
